        columnId: column.id,
        rowId,
        promptVersion: column.prompt_version,
        model: column.model,
        contentHash,
        status: "error",
        error: err instanceof Error ? err.message.slice(0, 800) : String(err),
        latencyMs: Date.now() - t0,
      });
    }
  });

  await recordLedger({
    kind: "run",
    columnId: column.id,
    model: column.model,
    cells: ran,
    inputTokens: inTok,
    outputTokens: outTok,
    costUsd,
  });

  return {
    ran,
    cached,
    skipped: 0,
    errors,
    costUsd,
    ms: Date.now() - started,
  };
}
