    }
  });

  await recordLedger({
    kind: "run",
    columnId: column.id,
    model: column.model,
    cells: ran,
    inputTokens: inTok,
    outputTokens: outTok,
    costUsd,
  });

  return {
    ran,
    cached,
    skipped: 0,
    errors,
    costUsd,
    ms: Date.now() - started,
  };
}
