{"files":[{"path":"lib/chat/title.ts","content":"export const DEFAULT_CHAT_TITLE = "New chat";

export function makeFallbackTitle(input: string) {
  const text = input
    .replace(/\s+/g, " ")
    .replace(/[`*_#>]/g, "")
    .trim();

  if (!text) {
    return DEFAULT_CHAT_TITLE;
  }

